const bloomButton=document.querySelector('#bloom-button');bloomButton.addEventListener('click',()=>{const open=bloomButton.classList.toggle('is-open');bloomButton.setAttribute('aria-pressed',String(open));bloomButton.setAttribute('aria-label',open?'Cerrar la flor':'Hacer florecer la flor');document.querySelector('#bloom-label').textContent=open?'Toca para cerrar la flor':'Toca para florecer ✨';document.querySelector('#bloom-status').textContent=open?'¡Tu flor ha florecido! Puedes volver a tocarla.':'Tu flor está esperando florecer.';if(open&&!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<12;i++){const p=document.createElement('i');p.className='bloom-spark';p.style.setProperty('--dx',(Math.cos(i*Math.PI/6)*110)+'px');p.style.setProperty('--dy',(Math.sin(i*Math.PI/6)*95-30)+'px');bloomButton.append(p);p.addEventListener('animationend',()=>p.remove(),{once:true})}}});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<6;i++){const p=document.createElement('i');p.className='garden-petal';p.setAttribute('aria-hidden','true');p.style.setProperty('--x',(8+i*17)+'%');p.style.setProperty('--duration',(15+i*2)+'s');p.style.setProperty('--delay',(-i*4)+'s');document.body.append(p)}}